<a class="back-link" href="<?= e(url('staff')) ?>">← กลับไปหน้าบัญชีสตาฟ</a><div class="page-heading"><div><h1><?= e($title) ?></h1><p>กำหนดบัญชีและสิทธิ์พื้นฐานของทีมงาน</p></div></div><section class="panel form-panel"><?php if($id): $helpQuery=db()->prepare('SELECT requested_at FROM password_help_requests WHERE user_id=?');$helpQuery->execute([$id]);if($helpQuery->fetchColumn()): ?><div class="alert">บัญชีนี้ขอตั้งรหัสผ่านใหม่ กรุณายืนยันตัวตนกับเจ้าของบัญชีก่อน ตั้งรหัสผ่านใหม่ด้านล่างแล้วแจ้งผ่านช่องทางส่วนตัว คำขอจะปิดหลังบันทึกรหัสใหม่สำเร็จ</div><?php endif;endif ?><?php require __DIR__ . '/../includes/errors.php'; ?><form method="post" class="form-stack"><?= csrf_field() ?><label>ชื่อสตาฟ <span class="required">*</span><input name="name" maxlength="150" value="<?= e($data['name']) ?>" required autocomplete="name"></label><?php if(!empty($data['student_id'])): ?><label>รหัสนักศึกษา<input value="<?= e($data['student_id']) ?>" readonly></label><?php endif ?><label>อีเมล<input type="email" name="email" maxlength="190" value="<?= e($data['email']??'') ?>" <?= empty($data['student_id'])?'required':'' ?> autocomplete="off"></label><label><?= $id?'ตั้งรหัสผ่านใหม่':'รหัสผ่าน' ?><input type="password" name="password" autocomplete="new-password" <?= $id?'':'required' ?>><small class="field-help">12–72 ไบต์ แนะนำอักษรอังกฤษ ตัวเลข และสัญลักษณ์<?= $id?' · เว้นว่างเพื่อใช้รหัสผ่านเดิม':'' ?></small></label><div class="form-grid"><label>บทบาท<select name="role"><option value="staff" <?= $data['role']==='staff'?'selected':'' ?>>สตาฟ (Staff)</option><option value="main_staff" <?= $data['role']==='main_staff'?'selected':'' ?>>สตาฟหลัก (Main Staff)</option></select></label><label>สถานะบัญชี<select name="is_active"><option value="1" <?= $data['is_active']?'selected':'' ?>>เปิดใช้งาน</option><option value="0" <?= !$data['is_active']?'selected':'' ?>>ปิดใช้งาน</option></select></label></div><fieldset><legend>ค่ายที่เข้าถึงได้</legend><p class="field-help">สตาฟเข้าถึงเฉพาะค่ายที่เลือก ส่วนสตาฟหลักเข้าถึงทุกค่าย</p><?php if(!$camps): ?><p class="muted">ยังไม่มีค่าย สามารถสร้างค่ายแล้วกลับมาเลือกภายหลังได้</p><?php endif ?><?php foreach($camps as $camp): ?><label class="checkbox-row"><input type="checkbox" name="camp_ids[]" value="<?= e($camp['id']) ?>" <?= in_array((int)$camp['id'],$campIds,true)?'checked':'' ?>><span><?= e($camp['name']) ?></span></label><?php endforeach ?></fieldset><div class="form-actions"><a class="button secondary" href="<?= e(url('staff')) ?>">ยกเลิก</a><button class="button primary">บันทึกบัญชี</button></div></form></section>
